def transform(grid):
    # Identify background color (most frequent or corners usually)
    # Assuming background is at (0,0)
    bg = grid[0][0]
    visited = set()
    components = []
    dr = [-1, 1, 0, 0]
    dc = [0, 0, -1, 1]

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if (r, c) not in visited and grid[r][c] != bg:
                color = grid[r][c]
                size = 0
                queue = [(r, c)]
                while queue:
                    curr_r, curr_c = queue.pop(0)
                    if (curr_r, curr_c) in visited:
                        continue
                    visited.add((curr_r, curr_c))
                    size += 1
                    for i in range(4):
                        nr, nc = curr_r + dr[i], curr_c + dc[i]
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                queue.append((nr, nc))
                components.append((size, color))

    if not components:
        return grid

    # Sort by size to find smallest and largest
    components.sort(key=lambda x: x[0])
    smallest_color = components[0][1]

    components.sort(key=lambda x: x[0], reverse=True)
    largest_color = components[0][1]

    # Apply transformation: Smallest Component Color -> Largest Component Color
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == smallest_color:
                grid[r][c] = largest_color

    return grid
